#include "stdafx.h"#include "Queue.h"#include "..\Lang.h"////~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структураtypedef struct : public SPROLOZ  {	COLORREF colorTxt;	COLORREF colorBkg;	bool bWater;	bool bSmall;  bool bOnlyDate;  bool bOnlyTime;  bool bTransparentBkg;  bool bTwoStrings;  bool bFullYear;  bool bLeftAlign;  } Queue_Timer;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция отображенияint PaintTimer(DefinePaint)  {  QueueP(Queue_Timer);  if (!p->bTransparentBkg)  {     	CMyBrush brush( hDC, p->colorBkg);	    CMyPen pen( hDC, p->colorBkg );	    brush.Rect(p->mRect);	    pen.Rect( p->mRect );  }	COLORREF old = ::SetTextColor( hDC, p->colorTxt );	UINT uFormat=DT_SINGLELINE|DT_VCENTER|DT_CENTER;	if (p->bLeftAlign)		uFormat=DT_SINGLELINE|DT_VCENTER|DT_LEFT;	__time64_t Time = ::GiveModelTime();	struct tm TM;	_localtime64_s( &TM, &Time );  int nMode;  if (p->bTransparentBkg)      nMode = ::SetBkMode( hDC, TRANSPARENT );  if (p->bOnlyTime)  {      char szTime[10];	  strftime( szTime, 9, "%H:%M:%S", &TM );      ::DrawText( hDC, szTime, lstrlen(szTime), &p->mRect, uFormat );  }  else  if (p->bOnlyDate)  {	  if (p->bFullYear)	  {		    char szDate[12];			strftime( szDate, 11, "%d.%m.%Y", &TM );			::DrawText( hDC, szDate, lstrlen(szDate), &p->mRect, uFormat );	  }	  else	  {			char szDate[10];			strftime( szDate, 9, "%d.%m.%y", &TM );			::DrawText( hDC, szDate, lstrlen(szDate), &p->mRect, uFormat );	  }  }  else  {	    if (!p->bTwoStrings)		{			char szTime[30];			if(p->bWater)				if(p->bSmall)					strftime( szTime, 29, "%H:%M %d.%m.%y", &TM );				else					strftime( szTime, 29, "%d-%m-%Y     %H:%M:%S", &TM );			else			{				if (p->bFullYear)					strftime( szTime, 29, "%d.%m.%Y %H:%M:%S", &TM );				else					strftime( szTime, 29, "%d.%m.%y %H:%M:%S", &TM );			}			::DrawText( hDC, szTime, lstrlen(szTime), &p->mRect, uFormat );		}		else		{			char szTime[30];			RECT rc1(p->mRect);			RECT rc2(p->mRect);			int nRectHeight=(p->mRect.bottom-p->mRect.top)/2;			rc1.bottom=rc1.top+nRectHeight;			rc2.top=rc1.bottom;			rc2.bottom=rc2.top+nRectHeight;			strftime( szTime, 29, "%H:%M:%S", &TM );			::DrawText( hDC, szTime, lstrlen(szTime), &rc1, uFormat );			strftime( szTime, 29, "%Y.%m.%d", &TM );			::DrawText( hDC, szTime, lstrlen(szTime), &rc2, uFormat );		}  }	::SetTextColor( hDC, old );  if (p->bTransparentBkg)    ::SetBkMode( hDC, nMode );  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddTimer(DefineTegs)  {  RECT rect;  if ( !ParserRect(teg[0].value,rect) ) return;  AddQueueEx(Queue_Timer);  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintTimer;  p->colorTxt= RGB(0,0,0);   p->colorBkg=RGB(192,192,192);  p->bWater=false;  p->bSmall=false;  p->bOnlyDate=false;  p->bOnlyTime=false;  p->bTransparentBkg=false;  p->bTwoStrings=false;  p->bFullYear=false;  p->bLeftAlign=false;  //    STegObj obj[] =    {	{ 'A', "colorTxt"  , &p->colorTxt     },	{ 'A', "colorBkg"  , &p->colorBkg     },	{ 'B', "water"  , &p->bWater     },	{ 'B', "small"  , &p->bSmall     },  { 'B', "onlydate"  , &p->bOnlyDate    },    { 'B', "onlytime"  , &p->bOnlyTime    },  { 'B', "transparentbkg"  , &p->bTransparentBkg    },  { 'B', "twostrings"  , &p->bTwoStrings    },  { 'B', "fullyear"  , &p->bFullYear    },  { 'B', "left"  , &p->bLeftAlign    },    };  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  p->mRect = rect;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~